steps.action:
curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { issue(identifier: \"WEB-1\") { id identifier title url } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { issues(filter: { identifier: { _in: [\"WEB-1\", \"WEB-2\"] } }) { nodes { id identifier title url } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "{ __type(name: \"IssueFilter\") { inputFields { name type { name kind ofType { name } } } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { teams { nodes { id key name } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { issues(filter: { team: { id: { eq: \"t-web\" } }, number: { _in: [1, 2] } }) { nodes { id identifier title } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { issues(filter: { team: { id: { eq: \"t-web\" } }, number: { in: [1, 2] } }) { nodes { id identifier title } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { comments(filter: { issue: { id: { eq: \"i-web-1\" } } }) { nodes { id body issue { id } user { name } } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "{ __type(name: \"CommentCreateInput\") { inputFields { name type { name kind ofType { name } } } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { users(filter: { name: { contains: \"Priya Nair\" } }) { nodes { id name } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "mutation { commentCreate(input: { issueId: \"i-web-2\", body: \"Tpyo in the title.\", createAsUser: \"u-priya\" }) { success comment { id body issue { id identifier } user { name } } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "mutation { commentDelete(id: \"c-1\") { success } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { c1: comments(filter: { issue: { id: { eq: \"i-web-1\" } } }) { nodes { id body } } c2: comments(filter: { issue: { id: { eq: \"i-web-2\" } } }) { nodes { id body } } }"
}'
